package com.volna.inventory_service.controller;import com.volna.inventory_service.dto.dashboard.*;import com.volna.inventory_service.dto.inventory.InventoryItemResponse;import com.volna.inventory_service.entity.InventoryItem;import com.volna.inventory_service.security.AuthenticatedUser;import com.volna.inventory_service.service.InventoryDashboardService;import org.springframework.security.core.annotation.AuthenticationPrincipal;import com.volna.inventory_service.exception.BadRequestException;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/v1/inventory/dashboard") public class InventoryDashboardController{private final InventoryDashboardService s;public InventoryDashboardController(InventoryDashboardService s){this.s=s;}@GetMapping public InventoryDashboardResponse dashboard(@AuthenticationPrincipal AuthenticatedUser u){return s.dashboard(u.authUserId());}@GetMapping("/insights")public InventoryInsightResponse insights(@AuthenticationPrincipal AuthenticatedUser u){return s.insights(u.authUserId());}@GetMapping("/expiring-soon")public List<InventoryItemResponse> expiring(@AuthenticationPrincipal AuthenticatedUser u,@RequestParam(defaultValue="7")int days){if(days<0||days>365)throw new BadRequestException("days must be between 0 and 365");return s.expiring(u.authUserId(),days).stream().map(this::map).toList();}private InventoryItemResponse map(InventoryItem x){return new InventoryItemResponse(x.getId(),x.getName(),x.getSku(),x.getCategory(),x.getUnit(),x.getStockLevel(),x.getMinimumStock(),x.getUnitCost(),x.getExpiryDate(),x.getStatus(),x.getSupplier());}}
